\set ON_ERROR_STOP on
begin;
delete from coverage_rule where document_id = (select id from program_document where id::text like 'c97bf9d0%');
with d as (select id, insurance_company_id from program_document where id::text like 'c97bf9d0%')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause)
select d.id, d.insurance_company_id, v.pn, v.sc, v.sp, v.vd, v.ct, v.la, v.cl from d cross join (values
(null,'общие-условия','услуги не предусмотренные договором программой','excluded',null,null,'п. 5.2 а)'),
(null,'общие-условия','услуги в организации не предусмотренной договором без согласования','excluded','выбор медорганизации вне договора должен быть согласован со Страховщиком',null,'п. 5.2 б)'),
(null,'общие-условия','услуги не назначенные лечащим врачом медицински необоснованные','excluded','включая лекарства и средства ухода без медицинских показаний',null,'п. 5.2 в)'),
(null,'общие-условия','обращение за пределами срока действия договора','excluded',null,null,'п. 5.2 г)'),
(null,'общие-условия','нарушение порядка предоставления медицинской помощи','excluded','помощь, оказанная с нарушением порядка, предусмотренного договором',null,'п. 5.2 д)'),
(null,'общие-условия','лечебно-диагностические мероприятия вне программы','excluded','если показаны мероприятия за рамками программы — врач обязан известить; за их назначение и финансирование Страховщик ответственности не несёт',null,'п. 5.3'),
(null,'общие-условия','неизвещение страховщика о страховом случае в срок','excluded','отказ возможен полностью или частично (срок извещения — п. 9.4.4)',null,'п. 5.1 а)'),
(null,'общие-исключения','алкогольное наркотическое токсическое опьянение','excluded',null,null,'п. 10.8 а)'),
(null,'общие-исключения','умышленное преступление','excluded',null,null,'п. 10.8 б)'),
(null,'общие-исключения','умышленное причинение себе вреда суицид','excluded','кроме случаев доведения противоправными действиями третьих лиц',null,'п. 10.8 в)'),
(null,'общие-исключения','военные действия волнения беспорядки митинги','excluded','кроме случаев исполнения служебных обязанностей',null,'п. 10.8 г)'),
(null,'общие-условия','передача полиса другому лицу','excluded',null,null,'п. 10.8 д)'),
(null,'общие-условия','искажённые сведения о застрахованном','excluded',null,null,'п. 10.8 е)'),
(null,'общие-условия','размер выплаты в пределах страховой суммы','conditional','выплата равна стоимости услуг по программе, но не более страховой суммы по договору',null,'п. 10.6.2'),
(null,'общие-условия','возмещение расходов застрахованного экспертиза целесообразности','needs_approval','при самостоятельной оплате — эксперты Страховщика в течение 45 рабочих дней дают заключение о целесообразности услуг; возмещение не позже 45 дней после заключения',null,'п. 10.6.3; п. 10.7'),
(null,'общие-условия','оплата счёта медорганизации срок','conditional','счета клиник оплачиваются в порядке договора со Страховщиком, но не позже 90 календарных дней с выставления счёта',null,'п. 10.7'),
(null,'общие-условия','расширение перечня услуг допсоглашением','needs_approval','перечень услуг/уровень обеспечения расширяется допсоглашением со Страховщиком',null,'п. 9.1.3')
) as v(pn, sc, sp, vd, ct, la, cl);
select count(*) from coverage_rule where document_id = (select id from program_document where id::text like 'c97bf9d0%');
commit;
